test_suite:
test('type-level: splits comma-separated string', () => {
  type T = Split<'a,b,c', ','>;
  const check: T = 'a';
  expect(['a', 'b', 'c']).toContain(check);
});

test('type-level: single segment returns itself', () => {
  type T = Split<'solo', ','>;
  const check: T = 'solo';
  expect(check).toBe('solo');
});

test('type-level: splits by pipe delimiter', () => {
  type T = Split<'x|y|z', '|'>;
  const v1: T = 'x';
  const v2: T = 'y';
  const v3: T = 'z';
  expect([v1, v2, v3]).toEqual(['x', 'y', 'z']);
});

test('type-level: two parts', () => {
  type T = Split<'hello:world', ':'>;
  const v1: T = 'hello';
  const v2: T = 'world';
  expect(v1).toBe('hello');
  expect(v2).toBe('world');
});

// __hidden__
test('type-level: empty second part', () => {
  type T = Split<'a,', ','>;
  const check: T = '';
  expect(check).toBe('');
});
